class Review(BaseModel):
    profile: str = Field(
        description="Guideline, research, or writing profile being violated."
    )
    location: str = Field(
        description="Paragraph or passage where the issue occurs."
    )
    comment: str = Field(
        description="Explain the violation and the correction to make."
    )

article.sections.14.blocks.6.text:
feedback = ReviewBatch(
    reviews=[
        Review(
            profile="terminology",
            location="paragraph 2",
            comment="The word 'leverage' is banned; replace it with direct wording.",
        )
    ]
)
